import {
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  Color
} from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreeGeometry } = ctx.THREE;

  const group = new ThreeGroup();

  // Colors
  const inkColor = new Color('#16161d');
  const paperColor = new Color('#e8ecf2');
  const accentColor = new Color('#ff2a38');
  const surfaceColor = new Color('#0b0b10');

  // Materials & Geometry
  // Hub frame bounds: x in [-3.5, 3.5], y in [-3, 2.5]
  // Backdrop plane representing the "engineered gradient surface"
  const backdropGeo = new ThreeGeometry(7.0, 5.5);

  // Custom TSL Material for Engineered Gradient & Subtle Grain
  const backdropMat = new MeshBasicNodeMaterial();

  // Create procedural vertical gradient with subtle noise grain simulating a premium look
  const uvs = uv();
  const gradFactor = uvs.y; // bottom-to-top gradient

  // Pseudo-random noise function for the subtle grain
  const noise = fract(sin(uvs.x.mul(12345.0).add(uvs.y.mul(67890.0))).mul(43758.5453));
  const grain = noise.mul(0.04); // subtle amplitude

  // Mix background surface (darker near-black) with the primary ink color (dark blue-grey)
  const baseColorNode = mix(vec3(surfaceColor.r, surfaceColor.g, surfaceColor.b), 
                            vec3(inkColor.r, inkColor.g, inkColor.b), 
                            gradFactor);

  // Add grain and a soft hint of the red accent at the center-right to feel premium
  const distFromCenter = smoothstep(0.1, 0.9, uvs.x);
  const tintedColorNode = mix(baseColorNode, vec3(accentColor.r, accentColor.g, accentColor.b), distFromCenter.mul(0.02));

  // Final composite color node with noise
  backdropMat.colorNode = tintedColorNode.add(vec3(grain));

  const backdropMesh = new ThreeMesh(backdropGeo, backdropMat);
  backdropMesh.position.set(0, -0.25, -0.1); // slightly offset back
  group.add(backdropMesh);

  // Foreground card image
  const cardGeo = new ThreeGeometry(4.0, 2.5);
  const cardMat = new MeshBasicNodeMaterial({ transparent: true });

  const cardMesh = new ThreeMesh(cardGeo, cardMat);
  // Position within the hub frame
  cardMesh.position.set(0, 0, 0.05);
  group.add(cardMesh);

  // Load physical image asset if available
  const imageUrl = config.imageUrl ?? (config.intent?.visualSpec?.imageUrl);
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      cardMat.map = texture;
      cardMat.needsUpdate = true;
    });
  }

  // Animation timeline - Gentle idle breathing to prevent a dead render
  const tl = gsap.timeline({ repeat: -1, yoyo: true });
  tl.to(cardMesh.position, {
    y: 0.04,
    duration: 3.5,
    ease: 'power1.inOut'
  });

  // Apply primitives
  const activePrimitives = [];
  const primitivesList = config.cinematicPrimitives ?? [];
  for (const prim of primitivesList) {
    if (ctx.primitives[prim.name]) {
      const res = ctx.primitives[prim.name](group, prim.params);
      activePrimitives.push(res);
    }
  }

  // Setup cleanup handler
  group.userData = {
    cleanup() {
      tl.kill();
      backdropGeo.dispose();
      backdropMat.dispose();
      cardGeo.dispose();
      cardMat.dispose();
      activePrimitives.forEach(p => {
        if (typeof p.cleanup === 'function') p.cleanup();
      });
    }
  };

  return group;
}

// Simple Helper TSL fract node
function fract(value) {
  return value.sub(value.floor());
}
